"""Generate provider protocol limits consumed by the Rust dispatcher."""
from __future__ import annotations

import argparse
from pathlib import Path

from codex_layout import REPOSITORY_ROOT
from codex_provider_limits import CALLBACK_QUEUE_LIMIT


OUTPUT = (
    REPOSITORY_ROOT
    / "workspaces/runtime/packages/runtime-providers/src/callback_queue_limit_generated.rs"
)


def render_rust_callback_queue_limit() -> str:
    return (
        "//! Generated by `studio_api.generate_provider_limits`; do not edit.\n"
        "//! Source: `codex_provider_limits.py`.\n"
        f"pub const CALLBACK_QUEUE_LIMIT: usize = {CALLBACK_QUEUE_LIMIT:_};\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write the generated Rust contract")
    mode.add_argument("--check", action="store_true", help="verify the generated Rust contract")
    args = parser.parse_args()

    expected = render_rust_callback_queue_limit()
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_text(encoding="utf-8") != expected:
            raise SystemExit(f"{OUTPUT.relative_to(REPOSITORY_ROOT)} is stale; run provider-limits:generate")
        return 0
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
